1: /**
2:  * Idempotent bootstrap seeding for US-01 and US-02.
3:  *
4:  * Rules (see `.opencode/skills/strapi-multi-country/SKILL.md` §3,
5:  * `specs/US-01-policyholder-vehicle-form.md` §3 and
6:  * `specs/US-02-plan-list.md` §3):
7:  * - natural key for `country-config` is `country`;
8:  * - natural key for `form-field` is `(country, key)`;
9:  * - natural key for `insurance-plan` is `(country, key)`;
10:  * - an entry is only created when no draft AND no published version exists,
11:  *   so restarting the stack never duplicates or mutates business-edited rows;
12:  * - new entries are published immediately (`status: 'published'`).
13:  */
14: import type { Core } from '@strapi/strapi';
15: 
16: import {
17:   countryConfigSeeds,
18:   type CountryConfigSeed,
19:   formFieldSeeds,
20:   type FormFieldSeed,
21:   insurancePlanSeeds,
22:   type InsurancePlanSeed,
23: } from './seed-data';
24: 
25: type SeedStatus = 'draft' | 'published';
26: 
27: interface SeedDocumentService<TData extends object> {
28:   findMany(params: {
29:     filters: Record<string, unknown>;
30:     status: SeedStatus;
31:   }): Promise<ReadonlyArray<unknown>>;
32:   create(params: { data: TData; status: SeedStatus }): Promise<unknown>;
33: }
34: 
35: /**
36:  * Narrow, typed view over the Strapi 5 Document Service.
37:  *
38:  * The cast keeps the bootstrap independent from generated content-type typings
39:  * (`types/generated/contentTypes.d.ts`); payloads are still validated by the
40:  * Document Service itself at runtime.
41:  */
42: const documentService = <TData extends object>(
43:   strapi: Core.Strapi,
44:   uid: string
45: ): SeedDocumentService<TData> =>
46:   strapi.documents(uid as never) as unknown as SeedDocumentService<TData>;
47: 
48: const existsWithStatus = async <TData extends object>(
49:   documents: SeedDocumentService<TData>,
50:   filters: Record<string, unknown>,
51:   status: SeedStatus
52: ): Promise<boolean> => {
53:   const entries = await documents.findMany({ filters, status });
54:   return entries.length > 0;
55: };
56: 
57: /**
58:  * `findMany` defaults to the draft version in Strapi 5, so both statuses are
59:  * queried explicitly: a published document still has a draft counterpart, but
60:  * checking both guarantees an unpublished hand-made entry is never duplicated.
61:  */
62: const entryExists = async <TData extends object>(
63:   documents: SeedDocumentService<TData>,
64:   filters: Record<string, unknown>
65: ): Promise<boolean> => {
66:   if (await existsWithStatus(documents, filters, 'draft')) {
67:     return true;
68:   }
69: 
70:   return existsWithStatus(documents, filters, 'published');
71: };
72: 
73: const seedCountryConfigs = async (strapi: Core.Strapi): Promise<void> => {
74:   const documents = documentService<CountryConfigSeed>(
75:     strapi,
76:     'api::country-config.country-config'
77:   );
78: 
79:   for (const config of countryConfigSeeds) {
80:     const exists = await entryExists(documents, { country: config.country });
81: 
82:     if (exists) {
83:       continue;
84:     }
85: 
86:     await documents.create({ data: config, status: 'published' });
87:     strapi.log.info(`[bootstrap] Seeded country-config for ${config.country}.`);
88:   }
89: };
90: 
91: const seedFormFields = async (strapi: Core.Strapi): Promise<void> => {
92:   const documents = documentService<FormFieldSeed>(strapi, 'api::form-field.form-field');
93: 
94:   for (const field of formFieldSeeds) {
95:     const exists = await entryExists(documents, {
96:       country: field.country,
97:       key: field.key,
98:     });
99: 
100:     if (exists) {
101:       continue;
102:     }
103: 
104:     await documents.create({ data: field, status: 'published' });
105:     strapi.log.info(`[bootstrap] Seeded form-field ${field.country}/${field.key}.`);
106:   }
107: };
108: 
109: const seedInsurancePlans = async (strapi: Core.Strapi): Promise<void> => {
110:   const documents = documentService<InsurancePlanSeed>(
111:     strapi,
112:     'api::insurance-plan.insurance-plan'
113:   );
114: 
115:   for (const plan of insurancePlanSeeds) {
116:     const exists = await entryExists(documents, {
117:       country: plan.country,
118:       key: plan.key,
119:     });
120: 
121:     if (exists) {
122:       continue;
123:     }
124: 
125:     await documents.create({ data: plan, status: 'published' });
126:     strapi.log.info(`[bootstrap] Seeded insurance-plan ${plan.country}/${plan.key}.`);
127:   }
128: };
129: 
130: export const seedContent = async (strapi: Core.Strapi): Promise<void> => {
131:   await seedCountryConfigs(strapi);
132:   await seedFormFields(strapi);
133:   await seedInsurancePlans(strapi);
134: 
135:   strapi.log.info(
136:     `[bootstrap] Seed verified: ${countryConfigSeeds.length} country configs, ` +
137:       `${formFieldSeeds.length} form fields and ${insurancePlanSeeds.length} insurance plans for CO/CL.`
138:   );
139: };

