9: /** Pure Step 1 snapshot: only keys still present in the Strapi field catalogue. */
10: export function pickKeys(
11:   values: Readonly<Record<string, FormValue>>,
12:   fields: ReadonlyArray<Pick<FormFieldConfig, 'key'>>,
13: ): Readonly<Record<string, FormValue>> {
14:   const picked: Record<string, FormValue> = {};
15:   for (const field of fields) {
16:     if (Object.prototype.hasOwnProperty.call(values, field.key)) {
17:       picked[field.key] = values[field.key];
18:     }
19:   }
20:   return picked;
21: }
22: 
23: /**
24:  * Exact simulated-pricing rule from `specs/US-02-plan-list.md` §2.2.
25:  * Integer-only arithmetic; never throws; neutral factors when keys are absent.
26:  */
27: export function calculateAdjustedPrice(
28:   basePrice: number,
29:   pricingStep1: Readonly<Record<string, FormValue>>,
30:   clock: Readonly<{ readonly today: Date; readonly currentYear: number }>,
31: ): PriceAdjustmentResult {
32:   const safeBasePrice = Number.isFinite(basePrice) && basePrice >= 0 ? Math.floor(basePrice) : 0;
33: 
34:   const vehicleValue = pricingStep1['vehicleYear'];
35:   const vehicleYear =
36:     typeof vehicleValue === 'number' && Number.isInteger(vehicleValue) ? vehicleValue : null;
37:   const vehicleAge =
38:     vehicleYear === null ? 0 : clamp(clock.currentYear - vehicleYear, 0, 20);
39:   const agePercent = vehicleAge <= 5 ? 0 : (vehicleAge - 5) * 2;
40: 
41:   const birthValue = pricingStep1['birthDate'];
42:   const birthIso = typeof birthValue === 'string' && ISO_DATE.test(birthValue) ? birthValue : null;
43:   const driverAge = birthIso === null ? null : ageOnDate(birthIso, clock.today);
44:   const driverPercent = driverAge === null ? 0 : driverAge < 25 ? 10 : driverAge >= 60 ? 5 : 0;
45: 
46:   const adjustmentPercent = agePercent + driverPercent;
47:   const finalPrice = Math.floor((safeBasePrice * (100 + adjustmentPercent) + 50) / 100);
48:   const reasons = [
49:     ...(agePercent > 0 ? [VEHICLE_REASON] : []),
50:     ...(driverPercent > 0 ? [DRIVER_REASON] : []),
51:   ];
52: 
53:   return { adjustmentPercent, reasons, finalPrice };
54: }
