49: export function ageOnDate(birthDateIso: string, today: Date): number | null {
50:   const birthDate = parseIsoDate(birthDateIso);
51:   if (!birthDate) {
52:     return null;
53:   }
54: 
55:   const localToday = new Date(today.getFullYear(), today.getMonth(), today.getDate());
56:   if (birthDate > localToday) {
57:     return null;
58:   }
